// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;

import org.junit.jupiter.api.Test;

/**
 * Pins the failure-aggregation contract of the packed f-tree's parallel grouped sink: a
 * {@link LmdbNativePackedFtree.PackedParallelDecline} is pure control flow ("this worker cannot run the parallel plan")
 * and must never surface as a real query failure. The {@link EncounterOrderFallback} unwinder reports every suppressed
 * non-fallback throwable as a real failure to rethrow, so attaching a decline as suppressed to a fallback would turn a
 * plan-divergence decline into a user-facing error and skip the sequential fallback that owns the correct answer.
 */
class LmdbNativePackedFtreeParallelFailureTest {

	/**
	 * Float SUM/AVG makes every worker throw the non-associative {@link EncounterOrderFallback}; a racing worker's
	 * decline must not ride along as a suppressed "real" failure — the sequential fallback still owns this query.
	 */
	@Test
	void declineArrivingAfterAFallbackMustNotBecomeARealFailure() {
		EncounterOrderFallback fallback = EncounterOrderFallback.distinctTermExtremaTie();

		Throwable combined = LmdbNativePackedFtree.addParallelFailure(fallback,
				new LmdbNativePackedFtree.PackedParallelDecline("worker plan diverged from the partitioned root"));

		assertSame(fallback, combined, "the fallback outranks the decline");
		assertNull(EncounterOrderFallback.realFailure(combined),
				"a decline is not a real failure: the sequential fallback must run instead of rethrowing");
	}

	/** The same contract with the arrival order reversed: the decline came first, the fallback outranks it. */
	@Test
	void fallbackArrivingAfterADeclineMustNotCarryItAsARealFailure() {
		EncounterOrderFallback fallback = EncounterOrderFallback.distinctTermExtremaTie();

		Throwable combined = LmdbNativePackedFtree.addParallelFailure(
				new LmdbNativePackedFtree.PackedParallelDecline("worker runtime unavailable"), fallback);

		assertSame(fallback, combined, "the fallback outranks the decline");
		assertNull(EncounterOrderFallback.realFailure(combined),
				"a decline is not a real failure: the sequential fallback must run instead of rethrowing");
	}

	/** Real failures still outrank declines in both directions, and real failures still aggregate by suppression. */
	@Test
	void realFailuresStillOutrankDeclinesAndAggregate() {
		IllegalStateException real = new IllegalStateException("worker failed");

		assertSame(real, LmdbNativePackedFtree.addParallelFailure(real,
				new LmdbNativePackedFtree.PackedParallelDecline("late decline")));
		assertSame(real, LmdbNativePackedFtree.addParallelFailure(
				new LmdbNativePackedFtree.PackedParallelDecline("early decline"), real));

		IllegalStateException second = new IllegalStateException("second worker failed");
		assertSame(real, LmdbNativePackedFtree.addParallelFailure(real, second));
		assertTrue(Arrays.asList(real.getSuppressed()).contains(second),
				"a second real failure is retained as suppressed on the first");

		EncounterOrderFallback fallback = EncounterOrderFallback.distinctTermExtremaTie();
		assertSame(fallback, LmdbNativePackedFtree.addParallelFailure(fallback, second));
		assertSame(second, EncounterOrderFallback.realFailure(fallback),
				"real failures suppressed while unwinding a fallback must keep surfacing");
	}
}
